    e.preventDefault();

    if (!title.trim()) return;

    createIssue.mutate(
      {
        title: title.trim(),
        description: description || undefined,
        status,
        assignee: assignee === "__none__" ? null : assignee,
        tags: tags
          ? tags
              .split(",")
              .map((t) => t.trim())
              .filter(Boolean)
