                    className="flex items-center gap-2 rounded-md border border-slate-200 bg-white px-3 py-2"
                  >
                    <Link
                      to={`/issues/${b.blockedId}`}
                      className="flex items-center gap-1 font-mono text-xs text-blue-600 hover:underline"
                      aria-label={`View blocked issue ${b.blockedId}`}
                    >
                      {b.blockedId}
                      <ExternalLink className="h-3 w-3" />
                    </Link>
                    <Badge
                      variant="secondary"
                      className={
                        b.status === "active"
                          ? "bg-amber-100 text-amber-700"
                          : "bg-green-100 text-green-700"
                      }
                    >
                      {b.status}
                    </Badge>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      ) : (
        <p className="py-2 text-sm text-slate-400">
          No blockages. This issue is not blocked by anything.
        </p>
      )}

      {/* Add blockage dialog */}
      <Dialog open={showAddDialog} onOpenChange={setShowAddDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Add Blockage</DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <label htmlFor="blockage-search" className="sr-only">
              Search for issues to block by
            </label>
            <Input
              id="blockage-search"
              ref={searchInputRef}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Search issues to block by..."
              autoFocus
              aria-label="Search for issues to block by"
            />
            {/* Selected issues */}
            {selectedIds.length > 0 && (
              <div className="flex flex-wrap gap-1">
                {selectedIds.map((id) => (
                  <Badge key={id} variant="secondary" className="gap-1">
                    {id}
                    <button
                      onClick={() => toggleSelect(id)}
                      className="ml-1 hover:text-red-600"
                      aria-label={`Remove selected issue ${id}`}
                    >
                      <X className="h-3 w-3" />
                    </button>
                  </Badge>
                ))}
              </div>
            )}
            {/* Search results */}
            {searchTerm && searchResults && (
              <div className="max-h-48 space-y-1 overflow-y-auto">
                {searchResults
                  .filter((i) => i.id !== issueId)
                  .map((issue) => (
                    <button
                      key={issue.id}
                      onClick={() => toggleSelect(issue.id)}
                      className={`flex w-full items-center gap-2 rounded-md border px-3 py-2 text-left text-sm transition-colors ${
                        selectedIds.includes(issue.id)
                          ? "border-blue-300 bg-blue-50"
                          : "border-slate-200 bg-white hover:bg-slate-50"
                      }`}
                      aria-label={`Select issue ${issue.id} as blocker`}
                    >
                      <span className="font-mono text-xs text-slate-400">
                        {issue.id}
                      </span>
                      <span className="truncate text-slate-700">
                        {issue.title}
                      </span>
                    </button>
                  ))}
                {searchResults.filter((i) => i.id !== issueId).length ===
                  0 && (
                  <p className="py-2 text-center text-sm text-slate-400">
                    No issues found.
                  </p>
                )}
              </div>
            )}
            <div className="flex justify-end gap-2">
              <Button
                variant="outline"
                size="sm"
                onClick={() => setShowAddDialog(false)}
              >
                Cancel
              </Button>
              <Button
                size="sm"
                onClick={handleAddBlockages}
                disabled={selectedIds.length === 0 || addBlockage.isPending}
              >
                {addBlockage.isPending ? "Adding..." : "Add Blockages"}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

